    }
  },
  "signal_basis": {
    "component_id": "C023_SIGNAL",
    "value": "Repeat the hypothesis comparison excluding incomplete traces and observe whether the ranking changes when uncertain evidence is removed.",
    "scope": "Tests sensitivity to uncertain evidence. Missing spans remain unknown, and incomplete exports must be accounted for where records permit.",
