      "rationale": "The cited spans supply the sensitivity operation, its ranking-change observation, and the limits concerning missing traces and incomplete exports."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C023_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The bounded sensitivity comparison does not require a further unresolved empirical relation."
